import socket
import subprocess
import os

class NetworkWorm:
    def __init__(self, name="Worm", port=54321):
        self.name = name
        self.port = port
        self.alive = True

    def connect(self, target_host):
        try:
            self.socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            self.socket.connect((target_host, self.port))
            self.socket.settimeout(5)  # Set a timeout for the connection
            print(f"Connection established to {target_host}:{self.port}")
        except (ConnectionRefusedError, socket.timeout) as e:
            print(f"Failed to connect to {target_host}:{self.port} - {e}")
            self.alive = False

    def send_copy(self, data):
        try:
            self.socket.sendall(data.encode())
            response = self.socket.recv(1024).decode()
            print(f"Worm sent data: {data} to: {response}")
        except Exception as e:
            print(f"Error sending data: {e}")

    def receive_data(self):
        try:
            self.data = self.socket.recv(1024).decode()
            print(f"Worm received data: {self.data}")
        except Exception as e:
            print(f"Error receiving data: {e}")

    def run(self):
        while self.alive:
            self.receive_data()
            if self.data is not None:
                self.send_copy(f"{self.name} - {self.data}")
            else:
                self.send_copy(f"{self.name} - Waiting for data...")

